#import "presentation/FYMainWindowController.h"
#import "FYLiveReadingTestFacts.h"
@interface LiveHostPeer : NSObject
@property(nonatomic,strong) FYLearningCoordinator *learningCoordinator;
@property(nonatomic,strong) NSTextView *grammarSourceTextView;
@property(nonatomic,strong) NSTextField *grammarSourceLabel,*grammarPinnedLabel;
@property(nonatomic,strong) NSButton *analyzeButton,*grammarPageAnalyzeButton;
@property(nonatomic) BOOL sourceHoverSuspended,learningAnalysisBusy;
@property(nonatomic,strong) FYAnalysisResult *currentAnalysis;
@property(nonatomic) NSUInteger histories,clears,statuses,hovers,chips,tabs;
@end
@implementation LiveHostPeer
- (NSColor *)uiInk{return NSColor.brownColor;}
- (NSColor *)uiMuted{return NSColor.grayColor;}
- (NSColor *)uiAccent{return NSColor.orangeColor;}
- (void)refreshHistory{self.histories++;}
- (void)clearAnalysisDisplay{self.clears++;}
- (void)refreshLearningStatus{self.statuses++;}
- (void)refreshSourceHoverTips{self.hovers++;}
- (void)refreshLiveChips{self.chips++;}
- (void)applyGrammarTabSelection{self.tabs++;}
@end
int main(void){@autoreleasepool{
 Check(NSApp==nil,@"original/extracted live host initializes no UI objects");LiveHostPeer *peer=[LiveHostPeer new];ReadingLearningFact *learning=[ReadingLearningFact new];learning.currentSentenceID=@"sentence";learning.currentVersion=1;learning.currentSourceText=@"青木\nここで待っている。";learning.currentTranslation=@"青木\n我在这里等。";peer.learningCoordinator=(FYLearningCoordinator *)learning;peer.grammarSourceTextView=(NSTextView *)TextFact(@"");peer.grammarSourceLabel=(NSTextField *)[ReadingLabelFact new];peer.grammarPinnedLabel=(NSTextField *)[ReadingLabelFact new];peer.analyzeButton=(NSButton *)[ReadingButtonFact new];peer.grammarPageAnalyzeButton=(NSButton *)[ReadingButtonFact new];FYMainWindowController *h=[[FYMainWindowController alloc]initWithHost:(id<FYMainWindowControllerHost>)peer];h.learningSourceTextView=(FYSelectableSourceTextView *)TextFact(@"");h.learningTranslationLabel=(NSTextField *)[ReadingLabelFact new];h.liveSourceEmptyLabel=(NSTextField *)[ReadingLabelFact new];h.liveSourceSelectionHintLabel=(NSTextField *)[ReadingLabelFact new];h.sourceReadingHeight=(NSLayoutConstraint *)[ReadingConstraintFact new];h.sourceReadingMinimumHeight=(NSLayoutConstraint *)[ReadingConstraintFact new];h.translationReadingMinimumHeight=(NSLayoutConstraint *)[ReadingConstraintFact new];h.wordPickArea=(NSStackView *)[ReadingBoundsFact new];ReadingWindowFact *window=[ReadingWindowFact new];window.contentView=[ReadingBoundsFact new];h.mainWindow=(NSWindow *)window;h.liveScreenSpeakerLabel=(NSTextField *)[ReadingLabelFact new];h.liveScreenDialogueLabel=(NSTextField *)[ReadingLabelFact new];h.learningPinnedLabel=(NSTextField *)[ReadingLabelFact new];h.pinSentenceButton=(NSButton *)[ReadingButtonFact new];
 [h refreshLearningSource];ReadingTextFact *text=(ReadingTextFact *)h.learningSourceTextView;Check([h.displayedSentenceID isEqual:@"sentence"]&&h.displayedVersion==1&&[h.displayedSourceText isEqual:learning.currentSourceText]&&[h.displayedTranslation isEqual:learning.currentTranslation]&&peer.clears==1&&h.vocabSelectionGeneration==1&&h.wordPickArea.hidden,@"actual live refresh retains clear/word generation and displayed4 writes");Check([text.textStorage.string isEqual:learning.currentSourceText]&&[peer.grammarSourceTextView.string isEqual:learning.currentSourceText]&&[h.learningTranslationLabel.attributedStringValue.string isEqual:learning.currentTranslation]&&[peer.grammarSourceLabel.stringValue isEqual:learning.currentTranslation],@"actual native text/grammar/translation writes preserve full characters");Check(h.liveSourceEmptyLabel.hidden&&!text.enclosingScrollView.hidden&&!h.liveSourceSelectionHintLabel.hidden&&h.sourceReadingMinimumHeight.constant==156&&h.translationReadingMinimumHeight.constant==156&&window.contentView.layouts==1,@"actual nonempty live layout/visibility/156 minima");Check(h.sourceReadingHeight.constant==ExpectedReadingHeight(text),@"actual production reading height uses real styled text and native width");Check([h.liveScreenSpeakerLabel.stringValue isEqual:@"青木"]&&[h.liveScreenDialogueLabel.stringValue isEqual:@"ここで待っている。"]&&peer.chips==1&&peer.statuses==1&&peer.hovers==1,@"actual canonical speaker helper/dialogue/Host refresh sequence");
 NSAttributedString *held=[text.textStorage copy];[h refreshLearningSource];Check(peer.clears==1&&h.vocabSelectionGeneration==1&&peer.hovers==1&&[text.textStorage isEqualToAttributedString:held],@"actual unchanged sentence avoids clear/word invalidation/hover/native text rewrite");peer.sourceHoverSuspended=YES;[h refreshLearningSource];Check(peer.hovers==2,@"actual suspended hover refresh preserved");peer.sourceHoverSuspended=NO;learning.currentTranslation=nil;[h refreshLearningSource];Check([h.learningTranslationLabel.attributedStringValue.string isEqual:@"等待该句译文"]&&[peer.grammarSourceLabel.stringValue isEqual:@"暂无该句译文"]&&h.translationReadingMinimumHeight.constant==156,@"actual waiting translation hints preserve source-present rule");
 learning.currentSourceText=@"";learning.currentSentenceID=@"";learning.currentVersion=0;[h refreshLearningSource];Check(h.sourceReadingMinimumHeight.constant==104&&h.translationReadingMinimumHeight.constant==104&&!h.liveSourceEmptyLabel.hidden&&text.enclosingScrollView.hidden&&h.liveSourceSelectionHintLabel.hidden&&[h.learningTranslationLabel.attributedStringValue.string isEqual:@"开始翻译后，译文会显示在这里。"]&&[peer.grammarSourceLabel.stringValue isEqual:@"还没有选择要分析的句子。"],@"actual compact empty state/native hints/minima preserved");
 NSString *source=@"青木\nここで待つ。";h.displayedSourceText=source;NSAttributedString *jp=[h liveReadingText:source japanese:YES];Check([jp.string isEqual:source]&&jp.length==source.length&&[[jp attribute:NSParagraphStyleAttributeName atIndex:3 effectiveRange:NULL]lineSpacing]==0,@"actual native formatting preserves original chars/indices and Japanese spacing");NSAttributedString *zh=[h liveReadingText:@"青木\n等一会。" japanese:NO];Check([[zh attribute:NSFontAttributeName atIndex:0 effectiveRange:NULL]pointSize]==13&&[[zh attribute:NSParagraphStyleAttributeName atIndex:3 effectiveRange:NULL]lineSpacing]==5,@"actual matching canonical source label allows secondary translated prefix");h.displayedSourceText=@"別人\n原文";zh=[h liveReadingText:@"青木\n等一会。" japanese:NO];Check([[zh attribute:NSFontAttributeName atIndex:0 effectiveRange:NULL]pointSize]==19,@"actual translated prefix without matching source remains body font");
 learning.currentSentenceID=@"sentence";learning.currentSourceText=@"source";learning.pinned=YES;learning.hasNewerSentence=YES;[h refreshLearningStatus];Check([h.learningPinnedLabel.stringValue isEqual:@"已固定 · 有新台词"]&&[peer.grammarPinnedLabel.stringValue isEqual:h.learningPinnedLabel.stringValue]&&[h.pinSentenceButton.title isEqual:@"跟随最新"]&&h.pinSentenceButton.enabled&&peer.analyzeButton.enabled&&peer.grammarPageAnalyzeButton.enabled&&peer.tabs==1,@"actual pin/newer/analyze native fields and tabs helper preserved");peer.learningAnalysisBusy=YES;[h refreshLearningStatus];Check(!peer.analyzeButton.enabled&&!peer.grammarPageAnalyzeButton.enabled&&h.pinSentenceButton.enabled,@"actual busy state disables analyze pair only");
 FYAnalysisResult *a=[FYAnalysisResult new];FYGrammarItem *g=[FYGrammarItem new];g.referenceLevel=@"N4";a.grammar=@[g];peer.currentAnalysis=a;Check([[h currentSentenceLevelTag]isEqual:@"N4"],@"actual first canonical reference level read");Check(NSApp==nil,@"actual original/extracted reading/format/height/state host remains headless, real UI only compiled");printf("PASS LiveReadingHostTests: %lu checks;exact original/extracted live/native font/measure/refresh algorithms,UI boundary facts,no UI objects\n",(unsigned long)checks);
}return 0;}
